import json,pathlib,duckdb,collections
ROOT=pathlib.Path('/home/dw/Projects/agent-sts2');O=pathlib.Path(__file__).resolve().parent;s=json.loads((ROOT/'paper/materials/20261024-issue51-own-fallback-ops/own-506-scope.json').read_text());meta={x['run_id']:x for x in s['runs']};c=duckdb.connect(':memory:');c.execute('SET threads=2');c.execute('CREATE TABLE allowed(run_id VARCHAR)');c.executemany('INSERT INTO allowed VALUES (?)',[(x,) for x in meta]);paths=[str(ROOT/x['path']) for x in s['verified_read_only_shards'] if x['table']=='sl_attempts'];c.execute('CREATE TEMP TABLE sl AS SELECT p.* FROM read_parquet(?) p JOIN allowed USING(run_id) WHERE off+len<=?',[paths,s['raw_stream_cutoffs']['sl-attempts']['max_bytes']]);data=c.execute("SELECT run_id,floor,count(*) events,bool_or(result='predicted_death') prediction,bool_or(reload_ok IS TRUE) successful_reload FROM sl GROUP BY run_id,floor").fetchall();perfloor={(a,b):{'events':n,'predicted_death_recorded':p,'successful_reload_recorded':r} for a,b,n,p,r in data};perrun={}
for run in meta:
 xs=[v for (r,f),v in perfloor.items() if r==run];p=any(x['predicted_death_recorded'] for x in xs);re=any(x['successful_reload_recorded'] for x in xs)
 label='reload_and_prediction' if re and p else 'reload_without_prediction' if re else 'prediction_without_successful_reload_record' if p else 'other_retry_evidence_or_scope_unknown' if meta[run]['attempt_scope']!='no_retry_evidence' else 'no_retry_evidence'
 perrun[run]={'run_id':run,'ascension':meta[run]['ascension'],'game_version':'unknown','attempt_stratum':label,'source_scope':meta[run]['attempt_scope'],'events':sum(x['events'] for x in xs),'predicted_death_recorded':p,'successful_reload_recorded':re}
inv=json.loads((O/'own-encounter-inventory.json').read_text());out=[]
for ctx in inv['contexts']:
 records=[]
 for row in ctx['opportunities']:
  records.append({'run_id':row['run_id'],'floor':row['floor'],'ascension':row['ascension'],'attempt_stratum':perrun[row['run_id']]['attempt_stratum'],'floor_attempt_evidence':perfloor.get((row['run_id'],row['floor']),{'events':0,'predicted_death_recorded':False,'successful_reload_recorded':False})})
 counter=collections.Counter((x['ascension'],x['attempt_stratum']) for x in records);out.append({'context':ctx['context'],'strata':[{'ascension':a,'attempt_stratum':b,'opportunities':n,'independent_runs':len({r['run_id'] for r in records if r['ascension']==a and r['attempt_stratum']==b})} for (a,b),n in sorted(counter.items())],'records':records})
(O/'own-attempt-strata.json').write_text(json.dumps({'source':'self:agent-sts2','game_version':'unknown','definition':'Run-level observed SL result/reload flags, plus per-floor event flags. Derived after the run for stratification only; never a decision trigger. No event record does not certify no SL. Prediction is not executed death.','eligible_runs':list(perrun.values()),'contexts':out},ensure_ascii=False,indent=2)+'\n')
